class WpfPool19 {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;static MainWindow main;static ClientSession session;static string root;
 static void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}
 static void Until(Func<bool> ready){var until=DateTime.UtcNow.AddSeconds(25);while(!ready()&&DateTime.UtcNow<until){Pump();Thread.Sleep(10);}Check(ready(),"async completes");}
 static T[] All<T>(DependencyObject parent) where T:DependencyObject {var list=new List<T>();for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);if(child is T)list.Add((T)child);list.AddRange(All<T>(child));}return list.ToArray();}
 static void Page(string name){typeof(MainWindow).GetMethod("Page",Flags).Invoke(main,new object[]{name});Pump();main.UpdateLayout();}
 static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Until(()=>!(bool)typeof(MainWindow).GetField("busy",Flags).GetValue(main));Pump();main.UpdateLayout();}
 static void Save(string name){main.UpdateLayout();var bitmap=new RenderTargetBitmap((int)main.ActualWidth,(int)main.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(main);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var s=File.Create(Path.Combine(root,name+".png")))png.Save(s);}
 static void Tables(){for(int round=0;round<8;round++){Page("Маршрутизация");Page("Серверы");Click(All<Button>(main).First(b=>b.Name=="serversSection1"));Click(All<Button>(main).First(b=>b.Name=="serversSection0"));var table=All<DataGrid>(main).First(t=>t.Name=="serverGrid");Check(table.ActualWidth>600&&table.ActualHeight>200,"server grid keeps available area after section switches");Check(table.Columns[0].ActualWidth>=150&&table.Columns[1].ActualWidth>=180&&table.Columns[2].ActualWidth>=120,"server columns never collapse");Check(!table.EnableColumnVirtualization,"server grouping does not recycle columns");}var choose=All<Button>(main).First(b=>Convert.ToString(b.Content)=="Выбрать подключение");var serverTable=All<DataGrid>(main).First(t=>t.Name=="serverGrid");Check(choose.TransformToAncestor(main).Transform(new Point()).Y-serverTable.TransformToAncestor(main).Transform(new Point(0,serverTable.ActualHeight)).Y>=12,"choose connection has spacing below table");Check(All<Button>(main).Any(b=>b.Name=="pingAllServers"),"ping all servers restored");Save("servers-repeated-switches");}
 static void Editor(){
  Page("Редактор стратегий");Until(()=>All<ComboBox>(main).Any(c=>c.Name=="wpfStrategyBasis"&&c.Items.Count>0));
  Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content)=="Отмена"),"editor no cancellation button");
  Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content).StartsWith("Сервисов")),"editor services only when checking");
  Check(All<ComboBox>(main).Any(c=>c.Name=="strategyEditMode"),"editor mode dropdown beside copy name");
  var block=All<TabControl>(main).First(c=>c.Name=="wpfParameterBlock");
  var strip=All<ScrollViewer>(main).First(c=>c.Name=="strategyBlockStrip");
  Check(block.Items.Count>0&&block.Items.Cast<string>().All(t=>!t.StartsWith("Блок")),"blocks are compact protocol tabs");
  Check(strip.HorizontalScrollBarVisibility==ScrollBarVisibility.Auto&&strip.VerticalScrollBarVisibility==ScrollBarVisibility.Disabled&&strip.ExtentWidth>strip.ViewportWidth,"single horizontally scrollable block row");strip.RaiseEvent(new System.Windows.Input.MouseWheelEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0,-120){RoutedEvent=UIElement.PreviewMouseWheelEvent});Pump();main.UpdateLayout();Check(strip.HorizontalOffset>0,"block strip scrolls with mouse wheel");strip.ScrollToHorizontalOffset(0);Pump();
  Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content)=="Добавить блок"||Convert.ToString(b.Content)=="Удалить блок"),"block text actions removed");
  var headers=All<TabItem>(block);double rowY=headers.First().TransformToAncestor(main).Transform(new Point()).Y;
  Check(headers.All(t=>Math.Abs(t.TransformToAncestor(main).Transform(new Point()).Y-rowY)<1),"all blocks stay on one line");
  Check(All<Button>(block).Count()==block.Items.Count&&All<Button>(block).All(b=>Convert.ToString(b.ToolTip)=="Удалить этот блок"),"upper block headers have only delete cross");
  int count=block.Items.Count;
  Click(All<Button>(block).Last());Check(block.Items.Count==count-1,"delete cross removes exactly one block");
  var menu=All<ListBox>(main).First(c=>c.Name=="wpfParameterName");
  menu.SelectedItem=menu.Items.Cast<string>().First(p=>p.EndsWith("--dpi-desync-split-pos"));menu.ScrollIntoView(menu.SelectedItem);Pump();main.UpdateLayout();
  var presence=All<CheckBox>(menu).First(c=>Convert.ToString(c.Tag)=="--dpi-desync-split-pos");presence.IsChecked=true;presence.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Pump();main.UpdateLayout();
  var table=All<DataGrid>(main).First(c=>c.Name=="strategyArgumentTable");
  Check(table.Columns.Select(c=>Convert.ToString(c.Header)).SequenceEqual(new[]{"Название","Значение","Пояснение"}),"argument table name value explanation");
  var row=table.Items.Cast<object>().First(o=>Convert.ToString(o.GetType().GetProperty("Flag").GetValue(o,null))=="--dpi-desync-split-pos");table.ScrollIntoView(row);Pump();main.UpdateLayout();
  var value=All<TextBox>(table).First(t=>t.DataContext==row);value.Text="3";value.RaiseEvent(new System.Windows.Input.KeyboardFocusChangedEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,0,value,menu){RoutedEvent=UIElement.LostKeyboardFocusEvent});Pump();
  var preview=All<TextBox>(main).First(t=>t.Name=="wpfBlockPreview");Check(preview.Text.Contains("--dpi-desync-split-pos=3"),"argument value table edits current block");
  menu.SelectedItem=menu.Items.Cast<string>().First(p=>p.EndsWith("--dpi-desync-split-pos"));menu.ScrollIntoView(menu.SelectedItem);Pump();main.UpdateLayout();
  presence=All<CheckBox>(menu).First(c=>Convert.ToString(c.Tag)=="--dpi-desync-split-pos");presence.IsChecked=false;presence.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Pump();
  Check(!preview.Text.Contains("--dpi-desync-split-pos="),"argument can be removed");Check(table.Items.Cast<object>().Any(o=>Convert.ToString(o.GetType().GetProperty("Flag").GetValue(o,null))=="--dpi-desync-split-pos"&&!(bool)o.GetType().GetProperty("Enabled").GetValue(o,null)),"disabled selected argument still has table explanation");
  Check(All<TextBlock>(table).Any(t=>t.Name=="strategyArgumentAdvice"&&t.Text.Length>50),"argument explanations present in table");Check(All<Button>(menu).Where(b=>b.IsVisible&&b.Tag!=null).All(b=>b.ToolTip is TextBlock&&((TextBlock)b.ToolTip).Text.Length>30&&ToolTipService.GetInitialShowDelay(b)==150),"hover shows real parameter explanation");Check(ScrollViewer.GetHorizontalScrollBarVisibility(menu)==ScrollBarVisibility.Disabled,"left arguments never push info icons offscreen");var infoButtons=All<Button>(menu).Where(b=>b.IsVisible&&b.Tag!=null).ToArray();Check(infoButtons.All(b=>b.TransformToAncestor(menu).Transform(new Point(b.ActualWidth,0)).X<=menu.ActualWidth),"all visible left info icons fit inside list");
  Check(preview.TransformToAncestor(main).Transform(new Point()).Y>main.ActualHeight/2,"block preview at bottom");Save("editor-structured");
  bool info=false;var infoTimer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(50)};infoTimer.Tick+=(s,e)=>{var dialog=Application.Current.Windows.Cast<Window>().FirstOrDefault(w=>w!=main);if(dialog==null)return;info=dialog.Title=="--dpi-desync-split-pos"&&All<TextBlock>(dialog).Any(t=>t.Text.Contains("Разбиение данных"));infoTimer.Stop();dialog.Close();};infoTimer.Start();Click(All<Button>(menu).First(b=>Convert.ToString(b.Tag)=="--dpi-desync-split-pos"));Check(info,"left argument info explains matching parameter");
  var mode=All<ComboBox>(main).First(c=>c.Name=="strategyEditMode");mode.SelectedIndex=1;Pump();Check(All<TextBox>(main).Any(t=>t.Name=="strategyBatText"&&t.IsVisible),"BAT mode dropdown works");Save("editor-bat");mode.SelectedIndex=0;Pump();
  var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(50)};bool prompted=false;timer.Tick+=(s,e)=>{var dialog=Application.Current.Windows.Cast<Window>().FirstOrDefault(w=>w!=main);if(dialog==null)return;prompted=dialog.Title=="Сервисы проверки копии";timer.Stop();dialog.Close();};timer.Start();Click(All<Button>(main).First(b=>Convert.ToString(b.Content)=="Проверить копию"));Check(prompted&&!session.Zapret.Running,"check-copy asks services and cancel starts no network");
 }
 static void DeploymentChecks(){
  ManagedDependencies.Ensure();using(var fixture=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ssh-fixture.exe"),"\""+root+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){try{int port=Int32.Parse(fixture.StandardOutput.ReadLine().Split('|')[1]);int tlsPort=Int32.Parse(fixture.StandardOutput.ReadLine().Split('|')[1]);string probePath=Path.Combine(root,"deployment-probe.py");File.WriteAllText(probePath,Deployment.PanelProbePython);var pythonInfo=new System.Diagnostics.ProcessStartInfo("python","\""+probePath+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};pythonInfo.EnvironmentVariables["MCRF_PANEL_URL"]="https://127.0.0.1:"+tlsPort+"/";pythonInfo.EnvironmentVariables["MCRF_PANEL_PORT"]=tlsPort.ToString();pythonInfo.EnvironmentVariables["MCRF_PANEL_USER"]="fixture";pythonInfo.EnvironmentVariables["MCRF_PANEL_PASS"]="fixture-panel";using(var python=System.Diagnostics.Process.Start(pythonInfo)){string line=python.StandardOutput.ReadLine();python.WaitForExit(15000);Check(python.HasExited&&python.ExitCode==0&&line.StartsWith("MCRF_RESULT|"),"actual TLS HTTPS panel readiness probe");var result=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<DeployResult>(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(line.Substring(12))));Deployment.ValidateResult(result,new DeployTarget{PanelPort=tlsPort});Check(result.certificate_sha256.Length==64,"TLS probe returns certificate fingerprint");}string hostKey=null;using(var ssh=new Renci.SshNet.SshClient("127.0.0.1",port,"fixture","fixture-password")){ssh.HostKeyReceived+=(s,e)=>{hostKey=Deployment.Fingerprint(e.HostKey);e.CanTrust=true;};ssh.Connect();using(var command=ssh.RunCommand("diagnostic"))Check(command.Result.Contains("MCRF_SSH_FIXTURE_OK"),"actual loopback SSH password authentication and command channel");}using(var ssh=new Renci.SshNet.SshClient("127.0.0.1",port,"fixture",new Renci.SshNet.PrivateKeyFile(Path.Combine(root,"ssh-fixture-key.pem")))){ssh.HostKeyReceived+=(s,e)=>e.CanTrust=Deployment.Fingerprint(e.HostKey)==hostKey;ssh.Connect();Check(ssh.IsConnected,"actual SSH private key authentication with pinned host fingerprint");}bool declined=false;using(var ssh=new Renci.SshNet.SshClient("127.0.0.1",port,"fixture","fixture-password")){ssh.HostKeyReceived+=(s,e)=>e.CanTrust=false;try{ssh.Connect();}catch{declined=true;}}Check(declined,"untrusted SSH host stops connection before deployment");}finally{if(!fixture.HasExited){fixture.Kill();fixture.WaitForExit(2000);}}}using(var client=new Renci.SshNet.SshClient("127.0.0.1",1,"fixture","fixture"))Check(!client.IsConnected,"SSH.NET resolves inside single EXE");
  var target=new DeployTarget{Host="192.0.2.1",User="root",Password="ssh-password",PanelUser="admin",PanelPassword="panel-password"};target.Validate();foreach(var recipe in DeployRecipe.All){string script=Deployment.BuildScript(recipe,target,"/tmp/mcrf-deploy-"+new string('a',32));Check(script.Contains("systemctl is-active")&&script.Contains("MCRF_RESULT|")&&!script.Contains("rm -rf"),"deployment verifies result and avoids broad deletion "+recipe.Id);Check(recipe.Url.Contains(recipe.Commit)&&recipe.Sha256.Length==64,"deployment installer pin and checksum "+recipe.Id);}
  string installer=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"openflux-installer.sh"));var pinned=Deployment.PinInstaller(DeployRecipe.All[1],installer);Check(pinned.Contains(DeployRecipe.All[1].CoreCommit)&&pinned.Contains("DEPLOY_REVISION='"+DeployRecipe.All[1].Commit+"'")&&!pinned.Contains("git clone --quiet --depth 1 --single-branch --branch main"),"verified OpenFlux installer pins panel and core sources");
  Check(Deployment.SafeLog("password: ssh-password panel-password",target).IndexOf("password",StringComparison.OrdinalIgnoreCase)<0,"deployment log never exposes passwords");Check(Deployment.Quote("a'b")=="'a'\"'\"'b'","SSH shell quoting handles apostrophe");bool rejected=false;try{Deployment.BuildScript(DeployRecipe.All[0],target,"/tmp");}catch(FormatException){rejected=true;}Check(rejected,"deployment path cannot target broad folder");target.Host="server;touch /tmp/wrong";rejected=false;try{target.Validate();}catch(FormatException){rejected=true;}Check(rejected,"deployment rejects shell-shaped host");
  Page("Автодеплой");Check(All<TextBox>(main).First(t=>t.Name=="deploySshPort").Text=="22"&&All<TextBox>(main).First(t=>t.Name=="deploySshUser").Text=="root","deployment SSH defaults");var auth=All<ComboBox>(main).First(t=>t.Name=="deployAuth");auth.SelectedIndex=1;Pump();Check(All<TextBox>(main).First(t=>t.Name=="deployKeyPath").IsVisible,"deployment key file selector");Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content)=="Добавить подключения"&&b.IsVisible),"deployment import hidden without actual connections");Check(All<TextBox>(main).First(t=>t.Name=="deploySshPort").ActualWidth<=100,"deployment port field compact");Save("deployment");
 }
 static void QwdttChecks(){string link=QwdttProfile.Link("Diagnostic QWDTT","192.0.2.7:56000","fixture-secret","abcdef_test_call");var p=QwdttProfile.Parse(link);Check(p.Host=="192.0.2.7"&&p.Port==56000&&p.Workers==9,"QWDTT current upstream share link parsed");var n=Links.Read(link).Single();Check(n.Protocol=="qwdtt"&&n.Host==p.Host&&!session.Core.HasEngine(n),"QWDTT import does not require an embedded engine");Page("Обновления");var type=All<ComboBox>(main).Single(c=>c.Name=="updatesType");Check(type.SelectedIndex==0,"updates default excludes optional engines");type.SelectedIndex=1;Pump();main.UpdateLayout();var grid=All<DataGrid>(main).Single(g=>g.Name=="updatesGrid");Check(grid.Items.Count==4,"all four optional engines displayed");var qrow=grid.Items.Cast<object>().Single(o=>((UpdateItem)o.GetType().GetProperty("Item").GetValue(o,null)).Id=="engine:qwdtt");grid.SelectedItem=qrow;Pump();var install=All<Button>(main).Single(b=>Convert.ToString(b.Content)=="Скачать движок");Check(install.IsEnabled,"QWDTT download button ready before checking catalog");Click(install);Check(session.Core.HasEngine(n),"QWDTT downloads from GitHub through UI without a ZIP picker");Check(!Application.Current.Windows.Cast<Window>().Any(w=>w!=main),"optional install opens no archive dialog");Check(!Directory.GetDirectories(session.Core.Engines.StorageRoot,".download-*").Any(),"UI download removes staging");Save("optional-engines");var state=new ClientState{Mode="proxy",AutoSelect=false,SelectedServerId=n.Id,Servers=new List<ServerNode>{n},Lists=new List<RouteList>(),IndependentWarpOutputs=true,VpnEnabled=true};session.Core.Check(session.Core.WriteConfig(state));Check(true,"QWDTT sing-box SOCKS outbound preflight");state.Mode="tun";session.Core.Check(session.Core.WriteConfig(state));Check(true,"QWDTT TUN preflight with direct helper exception");bool reject=false;try{QwdttProfile.Parse("qwdtt://config?peer=bad/command&pass=fixture");}catch(FormatException){reject=true;}Check(reject,"QWDTT invalid endpoint rejected");}
 [STAThread]static int Main(string[] args){try{root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("Choose a new isolated fixture.");Directory.CreateDirectory(root);Mcrf.Wpf.Program.ConfigureDpi();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Mcrf.Wpf.Program.LoadTheme(app);SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());main=new MainWindow(new[]{"--data",root});main.ShowActivated=false;main.WindowStartupLocation=WindowStartupLocation.Manual;main.Left=main.Top=-10000;main.Show();Until(()=>typeof(MainWindow).GetField("session",Flags).GetValue(main)!=null);session=(ClientSession)typeof(MainWindow).GetField("session",Flags).GetValue(main);Check(session.State.AutoSelectIntervalSeconds==60&&session.State.AutoSelectToleranceMs==50,"new auto defaults 60s 50ms");for(int i=0;i<20;i++)session.State.Servers.Add(new ServerNode{Name="DE Diagnostic "+i,Protocol="vless",Host="192.0.2."+ (i+1),Port=443,Link="vless://00000000-0000-0000-0000-000000000001@192.0.2."+(i+1)+":443",Source=i%2==0?"https://subscription.example/diagnostic":"",Latency=30+i});
  session.State.AutoSelect=false;Page("Главная");var auto=All<Button>(main).First(b=>b.Name=="homeAutoToggle");foreach(string expected in new[]{"Автовыбор первого","Автовыбор быстрого","Автовыбор выкл"}){Click(auto);Check(Convert.ToString(auto.Content)==expected,"homepage cycles "+expected);}Save("home");
  Page("Маршрутизация");var nav=(StackPanel)typeof(MainWindow).GetField("navigation",Flags).GetValue(main);Check(nav.Children.Cast<Button>().Select(b=>Convert.ToString(b.Content)).SequenceEqual(new[]{"Главная","Маршрутизация","Серверы","Zapret & Byetube","Мастер настройки","Журнал","Обновления","Автодеплой"}),"requested sidebar order");Check(All<Button>(main).Count(b=>b.Name.StartsWith("routingHosts_"))==3,"three hosts multi-select dropdowns above table");Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content)=="Дополнительные сервисы"),"no separate hosts services modal button");Save("routes");
  Page("Серверы");Check(All<Button>(main).Any(b=>b.Name=="serversSection2"&&Convert.ToString(b.Content)=="Протоколы"),"protocol section right of WARP");var update=All<Button>(main).First(b=>b.Name=="updateSubscriptions");Check(update.TransformToAncestor(main).Transform(new Point()).Y<190,"subscription refresh at section level");var method=All<ComboBox>(main).First(c=>c.Name=="autoSelectMethod");Check(method.ActualWidth<=311&&!All<TextBox>(main).First(t=>t.Name=="autoSelectInterval").IsVisible,"disabled auto selection is compact and hides interval");method.SelectedIndex=1;Until(()=>!(bool)typeof(MainWindow).GetField("busy",Flags).GetValue(main));Check(!All<TextBox>(main).First(t=>t.Name=="autoSelectTolerance").IsVisible,"first-working hides tolerance");method.SelectedIndex=2;Until(()=>!(bool)typeof(MainWindow).GetField("busy",Flags).GetValue(main));Check(All<TextBox>(main).First(t=>t.Name=="autoSelectInterval").TransformToAncestor(main).Transform(new Point()).X<All<TextBox>(main).First(t=>t.Name=="autoSelectTolerance").TransformToAncestor(main).Transform(new Point()).X,"interval left of tolerance");var table=All<DataGrid>(main).First(g=>g.Name=="serverGrid");Check(table.Columns.Count==5&&table.Columns[4].ActualWidth>=100,"three icon actions per server");Check(!All<Button>(main).Any(b=>Convert.ToString(b.Content)=="Копировать ссылку"||Convert.ToString(b.Content)=="Удалить"),"server standalone copy/delete buttons removed");Tables();Click(All<Button>(main).First(b=>b.Name=="serversSection2"));Check(All<DataGrid>(main).Single(g=>g.Name=="protocolsGrid").Items.Count==8,"protocols are structured as a table including QWDTT");Save("protocols");Click(All<Button>(main).First(b=>b.Name=="serversSection0"));Editor();DeploymentChecks();QwdttChecks();
  foreach(var size in new[]{new Size(1050,680),new Size(1366,865),new Size(1920,1080)}){main.Width=size.Width;main.Height=size.Height;Pump();foreach(string page in new[]{"Серверы","Маршрутизация","Zapret & Byetube","Автодеплой","Редактор стратегий"}){Page(page);if(page=="Редактор стратегий"){Until(()=>All<ComboBox>(main).Any(c=>c.Name=="wpfStrategyBasis"&&c.Items.Count>0));main.UpdateLayout();var arguments=All<DataGrid>(main).First(t=>t.Name=="strategyArgumentTable");Check(arguments.Background==System.Windows.Media.Brushes.Transparent&&arguments.RowBackground==System.Windows.Media.Brushes.Transparent,"argument table has no separate dark surface at "+size.Width);var panelScroll=All<ScrollViewer>(arguments).First(v=>v.Name=="DG_ScrollViewer");Check(panelScroll.ScrollableWidth<1,"argument table fits small window without horizontal scrolling at "+size.Width);if(size.Height<760)Check(All<TextBox>(main).First(t=>t.Name=="wpfBlockPreview").Height<=64,"compact preview leaves room for argument rows");Check(arguments.Columns[0].ActualWidth>=120&&arguments.Columns[1].ActualWidth>=135&&arguments.Columns[2].ActualWidth>=180,"argument table widths at "+size.Width);Check(All<TextBox>(arguments).All(t=>t.TextWrapping==TextWrapping.NoWrap),"argument fields stay single-line at "+size.Width);Check(All<TextBlock>(arguments).Where(t=>t.Name=="strategyValueDisplay").All(t=>t.TextTrimming==TextTrimming.CharacterEllipsis),"long value display uses ellipsis at "+size.Width);var fileValue=All<TextBox>(arguments).FirstOrDefault(t=>t.ToolTip!=null&&Convert.ToString(t.ToolTip).Trim('"').EndsWith(".bin"));if(fileValue!=null){var currentPreview=All<TextBox>(main).First(t=>t.Name=="wpfBlockPreview");string previous=currentPreview.Text;Check(!System.IO.Path.IsPathRooted(fileValue.Text),"BIN value shows file name without giant path at "+size.Width);fileValue.RaiseEvent(new System.Windows.Input.KeyboardFocusChangedEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,0,main,fileValue){RoutedEvent=UIElement.GotKeyboardFocusEvent});Check(fileValue.Text==Convert.ToString(fileValue.ToolTip),"BIN full path available on focus at "+size.Width);fileValue.RaiseEvent(new System.Windows.Input.KeyboardFocusChangedEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,0,fileValue,main){RoutedEvent=UIElement.LostKeyboardFocusEvent});Check(currentPreview.Text==previous,"reading BIN path does not edit strategy at "+size.Width);}Check(All<TextBlock>(arguments).Where(t=>t.Name=="strategyArgumentAdvice"||t.Name=="strategyArgumentLabel").All(t=>t.TextWrapping==TextWrapping.Wrap&&Double.IsPositiveInfinity(t.MaxHeight)),"argument text wraps without height clipping at "+size.Width);}System.Windows.Input.Keyboard.ClearFocus();Save(page+"-"+size.Width);var sideModules=(StackPanel)typeof(MainWindow).GetField("modulePanel",Flags).GetValue(main);var contentBody=(Panel)typeof(MainWindow).GetField("body",Flags).GetValue(main);Check(Math.Abs(sideModules.TransformToAncestor(main).Transform(new Point(0,sideModules.ActualHeight)).Y-contentBody.TransformToAncestor(main).Transform(new Point(0,contentBody.ActualHeight)).Y+12)<2,"sidebar toggles anchored at card bottom "+page+" "+size.Width);foreach(var button in All<Button>(main).Where(b=>b.IsVisible&&b.Style==(Style)main.FindResource("IconAction")&&page!="Редактор стратегий"))Check(button.ActualWidth>=28&&button.ActualHeight>=28,"icon hit area "+page+" "+size.Width);}}
  foreach(var icon in All<Button>(main).Where(b=>b.Style==(Style)main.FindResource("IconAction"))){var content=icon.Content as FrameworkElement;if(content!=null)Check(content.Width+icon.Padding.Left+icon.Padding.Right+2<=icon.Width&&content.Height+icon.Padding.Top+icon.Padding.Bottom+2<=icon.Height,"icon drawing fits padded button");}
  Check(!session.Core.Running&&!session.Zapret.Running&&!session.Telegram.Running,"tests leave actual interception stopped");main.Close();Until(()=>!main.IsVisible);Console.WriteLine("OK "+checks+" pool19 checks");app.Shutdown();return 0;
 }catch(Exception ex){Console.WriteLine(ex);if(main!=null)main.Close();return 1;}}
